package com.smartresponse.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="emergency_feedback") public class EmergencyFeedback {@Id @GeneratedValue private UUID id;@ManyToOne(optional=false) @JoinColumn(name="emergency_id") private Emergency emergency;@ManyToOne(optional=false) @JoinColumn(name="reporter_id") private AppUser reporter;private int rating;private String comments;private Instant createdAt=Instant.now();protected EmergencyFeedback(){}public EmergencyFeedback(Emergency e,AppUser u,int r,String c){emergency=e;reporter=u;rating=r;comments=c;}public UUID getId(){return id;}public Emergency getEmergency(){return emergency;}public AppUser getReporter(){return reporter;}public int getRating(){return rating;}public String getComments(){return comments;}public Instant getCreatedAt(){return createdAt;}}
